    if not arr:
        return 0
    best_product = arr[0]
    current_product = arr[0]
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            # Extending strictly increasing subsequence
            current_product *= arr[i]
        else:
            # Restart new subsequence
            current_product = arr[i]
        if current_product > best_product:
            best_product = current_product
    return best_product

